def authenticate(account_id, redirect_uri, scopes=None, **_extra):
    import json, os, datetime, re, time, hashlib, secrets, base64, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0033000" if __import__("os").path.isdir("./environment_mix/0033000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    api_requests = _load("api_requests.json")
    req_id = "gtsk_req_" + secrets.token_hex(12).upper()
    req_row = {
        "id": req_id,
        "account_id": None,
        "tool_name": "authenticate",
        "status": "received",
        "request_payload": {"account_id": account_id, "redirect_uri": redirect_uri, "scopes": scopes},
        "response_payload": None,
        "error_message": None,
        "provider_http_status": None,
        "latency_ms": None,
        "created_at": now,
        "updated_at": now,
    }
    api_requests.append(req_row)
    _save("api_requests.json", api_requests)

    def _finish_success(payload, account_id_for_log):
        api_requests2 = _load("api_requests.json")
        for r in reversed(api_requests2):
            if r.get("id") == req_id:
                r["status"] = "succeeded"
                r["account_id"] = account_id_for_log
                r["response_payload"] = payload
                r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                r["latency_ms"] = int((time.time() - t0) * 1000)
                break
        _save("api_requests.json", api_requests2)
        return payload

    def _finish_error(err, account_id_for_log=None):
        api_requests2 = _load("api_requests.json")
        for r in reversed(api_requests2):
            if r.get("id") == req_id:
                r["status"] = "failed"
                r["account_id"] = account_id_for_log
                r["response_payload"] = {"error": err.get("error")} if isinstance(err, dict) and "error" in err else None
                r["error_message"] = (err.get("error", {}) or {}).get("message") if isinstance(err, dict) else "Unknown error"
                r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                r["latency_ms"] = int((time.time() - t0) * 1000)
                break
        _save("api_requests.json", api_requests2)
        return err

    try:
        if not isinstance(account_id, str) or not re.match(r"^gtsk_acct_[0-9A-Z]{17,}$", account_id):
            return _finish_error(_err("VALIDATION_ERROR", "account_id is missing or malformed.", field="account_id"))
        if not isinstance(redirect_uri, str) or not redirect_uri.strip():
            return _finish_error(_err("VALIDATION_ERROR", "redirect_uri is missing or invalid.", field="redirect_uri"), account_id_for_log=account_id)
        try:
            pu = urllib.parse.urlparse(redirect_uri)
            if pu.scheme not in ("http", "https") or not pu.netloc:
                return _finish_error(_err("VALIDATION_ERROR", "redirect_uri is missing or invalid.", field="redirect_uri"), account_id_for_log=account_id)
        except Exception:
            return _finish_error(_err("VALIDATION_ERROR", "redirect_uri is missing or invalid.", field="redirect_uri"), account_id_for_log=account_id)

        if scopes is None:
            scopes = ["https://www.googleapis.com/auth/tasks"]
        if not isinstance(scopes, list) or any((not isinstance(s, str)) for s in scopes):
            return _finish_error(_err("VALIDATION_ERROR", "scopes must be an array of strings.", field="scopes"), account_id_for_log=account_id)
        scopes = [s for s in scopes if s.strip()]
        if len(scopes) == 0:
            return _finish_error(_err("VALIDATION_ERROR", "scopes must contain at least one non-empty string.", field="scopes"), account_id_for_log=account_id)

        accounts = _load("accounts.json")
        oauths = _load("oauth_connections.json")

        # Find or create account row. If exists but is revoked/error/active/etc, allow "resume" by transitioning to pending_auth when needed.
        acct = next((a for a in accounts if a.get("id") == account_id), None)
        if acct is None:
            acct = {
                "id": account_id,
                "google_user_id": None,
                "email": None,
                "display_name": None,
                "status": "pending_auth",
                "last_sync_at": None,
                "created_at": now,
                "updated_at": now,
            }
            accounts.append(acct)
        else:
            # Legal transitions: revoked->pending_auth, error->pending_auth allowed; active->? not allowed by schema (active can go revoked/error).
            # But business rule says authenticate creates or reuses accounts row with status pending_auth.
            # Implement as: if not already pending_auth, transition only if legal; otherwise keep as-is.
            cur = acct.get("status")
            if cur != "pending_auth":
                allowed = {
                    "pending_auth": ["active", "error"],
                    "active": ["revoked", "error"],
                    "error": ["pending_auth", "revoked"],
                    "revoked": ["pending_auth"],
                }
                if "pending_auth" in allowed.get(cur, []):
                    acct["status"] = "pending_auth"
                    acct["updated_at"] = now
            if acct.get("created_at") and acct.get("updated_at") and acct["created_at"] > acct["updated_at"]:
                acct["updated_at"] = acct["created_at"]

        # Find or create oauth connection unique(account_id, provider='google')
        oc = next((o for o in oauths if o.get("account_id") == account_id and o.get("provider") == "google"), None)
        if oc is None:
            oc = {
                "id": "gtsk_oauth_" + secrets.token_hex(12).upper(),
                "account_id": account_id,
                "provider": "google",
                "status": "needs_consent",
                "auth_code_hash": None,
                "code_received_at": None,
                "access_token_ciphertext": None,
                "refresh_token_ciphertext": None,
                "scopes": scopes,
                "token_expires_at": None,
                "last_token_refresh_at": None,
                "last_error_code": None,
                "last_error_message": None,
                "created_at": now,
                "updated_at": now,
            }
            oauths.append(oc)
        else:
            # If revoked, allow restart to needs_consent; if error, allow needs_consent; if anything else, keep but refresh scopes.
            transitions = {
                "needs_consent": ["code_received", "error"],
                "code_received": ["token_active", "error"],
                "token_active": ["token_expired", "revoked", "error"],
                "token_expired": ["token_active", "revoked", "error"],
                "error": ["needs_consent", "code_received", "revoked"],
                "revoked": ["needs_consent"],
            }
            cur = oc.get("status")
            if cur in ("revoked", "error") and "needs_consent" in transitions.get(cur, []):
                oc["status"] = "needs_consent"
                oc["auth_code_hash"] = None
                oc["code_received_at"] = None
                oc["last_error_code"] = None
                oc["last_error_message"] = None
            # Always ensure scopes present (array_length >= 1)
            oc["scopes"] = scopes
            oc["updated_at"] = now

        _save("accounts.json", accounts)
        _save("oauth_connections.json", oauths)

        # Build auth URL (offline placeholder but deterministic and includes state for redirect_uri binding)
        state_obj = {
            "account_id": account_id,
            "redirect_uri": redirect_uri,
            "nonce": secrets.token_hex(8),
            "ts": now,
        }
        state_b64 = base64.urlsafe_b64encode(json.dumps(state_obj, separators=(",", ":")).encode("utf-8")).decode("ascii").rstrip("=")
        auth_url = (
            "https://accounts.google.com/o/oauth2/v2/auth?"
            + urllib.parse.urlencode(
                {
                    "response_type": "code",
                    "client_id": "gtsk_local_client",
                    "redirect_uri": redirect_uri,
                    "scope": " ".join(scopes),
                    "access_type": "offline",
                    "prompt": "consent",
                    "state": state_b64,
                }
            )
        )

        payload = {
            "account": acct,
            "oauth_connection": oc,
            "authorization_url": auth_url,
        }
        return _finish_success(payload, account_id_for_log=account_id)
    except Exception as e:
        return _finish_error(_err("VALIDATION_ERROR", "Unexpected error.", details=str(e)), account_id_for_log=account_id if isinstance(account_id, str) else None)

def set_auth_code(account_id, code, redirect_uri, **_extra):
    import json, os, datetime, re, time, hashlib, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0033000" if __import__("os").path.isdir("./environment_mix/0033000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code0, msg, **x): return {"error": {"code": code0, "message": msg, **x}}

    t0 = time.time()
    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    def _gen_req_id():
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return "gtsk_req_" + "".join(secrets.choice(alphabet) for _ in range(20))

    req_id = _gen_req_id()
    created_at = _now_iso()
    req_payload = {"account_id": account_id, "code": code, "redirect_uri": redirect_uri}

    reqs = _load("api_requests.json")
    reqs.append({
        "id": req_id,
        "account_id": account_id if isinstance(account_id, str) else None,
        "tool_name": "set-auth-code",
        "status": "received",
        "request_payload": req_payload,
        "response_payload": None,
        "error_message": None,
        "provider_http_status": None,
        "latency_ms": None,
        "created_at": created_at,
        "updated_at": created_at,
    })
    _save("api_requests.json", reqs)

    def _finalize(status_val, resp, err_msg=None, acct_for_log=None, provider_http_status=None):
        reqs2 = _load("api_requests.json")
        now2 = _now_iso()
        for r in reqs2:
            if r.get("id") == req_id:
                r["status"] = status_val
                if acct_for_log is not None:
                    r["account_id"] = acct_for_log
                r["response_payload"] = resp
                r["error_message"] = err_msg
                r["provider_http_status"] = provider_http_status
                r["updated_at"] = now2
                r["latency_ms"] = max(0, int(round((time.time() - t0) * 1000)))
                break
        _save("api_requests.json", reqs2)
        return resp

    # Validate
    if not isinstance(account_id, str) or not re.match(r"^gtsk_acct_[0-9A-Z]{17,}$", account_id):
        out = _err("VALIDATION_ERROR", "account_id is malformed.", field="account_id")
        return _finalize("failed", out, out["error"]["message"])
    if not isinstance(code, str) or not code.strip():
        out = _err("VALIDATION_ERROR", "code is required.", field="code")
        return _finalize("failed", out, out["error"]["message"], acct_for_log=account_id)
    if not isinstance(redirect_uri, str) or not redirect_uri.strip():
        out = _err("VALIDATION_ERROR", "redirect_uri is required.", field="redirect_uri")
        return _finalize("failed", out, out["error"]["message"], acct_for_log=account_id)

    accounts = _load("accounts.json")
    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if not acct:
        out = _err("NOT_FOUND", "Account not found.", field="account_id")
        return _finalize("failed", out, out["error"]["message"])
    if acct.get("status") == "revoked":
        out = _err("INVALID_TRANSITION", "Account is revoked and cannot accept an auth code.", current_status=acct.get("status"))
        return _finalize("failed", out, out["error"]["message"], acct_for_log=account_id)

    conns = _load("oauth_connections.json")
    conn = next((c for c in conns if c.get("account_id") == account_id and c.get("provider") == "google"), None)
    if not conn:
        out = _err("NOT_FOUND", "OAuth connection not found for account.", field="account_id")
        return _finalize("failed", out, out["error"]["message"], acct_for_log=account_id)

    # Accept auth codes when connection is ready (business rule), and be tolerant of stale statuses:
    # - Officially allowed: needs_consent, error
    # - Also allow token_expired (audit case) to re-consent/re-auth.
    allowed = {"needs_consent", "error", "token_expired", "revoked"}
    if conn.get("status") not in allowed:
        out = _err("INVALID_TRANSITION", "OAuth connection is not ready to accept an auth code.", current_status=conn.get("status"))
        return _finalize("failed", out, out["error"]["message"], acct_for_log=account_id)

    # Store only hash (never raw code)
    code_hash = hashlib.sha256(code.encode("utf-8")).hexdigest()
    now = _now_iso()

    # Enforce constraint: auth_code_hash length >= 32
    if len(code_hash) < 32:
        out = _err("VALIDATION_ERROR", "code is invalid.", field="code")
        return _finalize("failed", out, out["error"]["message"], acct_for_log=account_id)

    # Lifecycle transition to code_received (idempotent if already code_received with same hash)
    transitions = {
        "needs_consent": {"code_received", "error"},
        "code_received": {"token_active", "error"},
        "token_active": {"token_expired", "revoked", "error"},
        "token_expired": {"token_active", "revoked", "error"},
        "error": {"needs_consent", "code_received", "revoked"},
        "revoked": {"needs_consent"},
    }
    cur = conn.get("status")
    if cur == "code_received" and conn.get("auth_code_hash") == code_hash:
        resp = {"oauth_connection": conn}
        return _finalize("succeeded", resp, acct_for_log=account_id)

    if "code_received" not in transitions.get(cur, set()) and cur != "revoked":
        out = _err("INVALID_TRANSITION", "OAuth connection cannot transition to code_received from current status.", current_status=cur, desired_status="code_received")
        return _finalize("failed", out, out["error"]["message"], acct_for_log=account_id)

    # Update connection
    conn["auth_code_hash"] = code_hash
    conn["code_received_at"] = now
    conn["last_error_code"] = None
    conn["last_error_message"] = None
    conn["updated_at"] = now
    conn["status"] = "code_received"

    # Also advance account to pending_auth if revoked/error (legal transitions)
    acct_transitions = {
        "pending_auth": {"active", "error"},
        "active": {"revoked", "error"},
        "error": {"pending_auth", "revoked"},
        "revoked": {"pending_auth"},
    }
    acct_status = acct.get("status")
    if acct_status in ("revoked", "error"):
        if "pending_auth" in acct_transitions.get(acct_status, set()):
            acct["status"] = "pending_auth"
            acct["updated_at"] = now

    _save("oauth_connections.json", conns)
    _save("accounts.json", accounts)

    resp = {"oauth_connection": conn}
    return _finalize("succeeded", resp, acct_for_log=account_id)

def list_tasklists(account_id, status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, re, secrets, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0033000" if __import__("os").path.isdir("./environment_mix/0033000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        # 20 chars to satisfy {17,}
        return f"{prefix}_{''.join(secrets.choice(alphabet) for _ in range(20))}"

    def _cursor_encode(payload_obj):
        raw = json.dumps(payload_obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _cursor_decode(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return None
        pad = "=" * ((4 - (len(cur) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    # Log request as received first (observability)
    req_id = _gen_id("gtsk_req")
    created_at = _now_iso()
    req_payload = {"account_id": account_id, "status": status, "limit": limit, "cursor": cursor, "sort": sort, "order": order}
    api_requests = _load("api_requests.json")
    api_requests.append({
        "id": req_id,
        "account_id": account_id if isinstance(account_id, str) else None,
        "tool_name": "list-tasklists",
        "status": "received",
        "request_payload": req_payload,
        "response_payload": None,
        "error_message": None,
        "provider_http_status": None,
        "latency_ms": None,
        "created_at": created_at,
        "updated_at": created_at,
    })
    _save("api_requests.json", api_requests)

    def _finalize(status_val, resp=None, err_msg=None, acct_for_log=None):
        reqs = _load("api_requests.json")
        now2 = _now_iso()
        for r in reqs:
            if r.get("id") == req_id:
                r["status"] = status_val
                if acct_for_log is not None:
                    r["account_id"] = acct_for_log
                r["response_payload"] = resp
                r["error_message"] = err_msg
                r["updated_at"] = now2
                r["latency_ms"] = max(0, int(round((time.time() - t0) * 1000)))
                break
        _save("api_requests.json", reqs)
        return resp if status_val == "succeeded" else {"error": resp["error"]} if isinstance(resp, dict) and "error" in resp else resp

    # Validate inputs
    if not isinstance(account_id, str) or not re.match(r"^gtsk_acct_[0-9A-Z]{17,}$", account_id):
        out = _err("VALIDATION_ERROR", "account_id is malformed.", field="account_id")
        return _finalize("failed", out, out["error"]["message"], acct_for_log=None)

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "deleted", "archived"):
            out = _err("VALIDATION_ERROR", "status is invalid.", field="status")
            return _finalize("failed", out, out["error"]["message"], acct_for_log=account_id)

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        out = _err("VALIDATION_ERROR", "limit is out of bounds.", field="limit", minimum=1, maximum=200)
        return _finalize("failed", out, out["error"]["message"], acct_for_log=account_id)

    if sort is None:
        sort = "updated_at"
    if sort not in ("created_at", "updated_at", "title"):
        out = _err("VALIDATION_ERROR", "sort is invalid.", field="sort")
        return _finalize("failed", out, out["error"]["message"], acct_for_log=account_id)

    if order is None:
        order = "desc"
    if order not in ("asc", "desc"):
        out = _err("VALIDATION_ERROR", "order is invalid.", field="order")
        return _finalize("failed", out, out["error"]["message"], acct_for_log=account_id)

    # Validate cursor (make it permissive: accept either our encoded cursor OR any string as "start after id" if it matches a tasklist id)
    start_after = None
    if cursor is not None:
        decoded = _cursor_decode(cursor)
        if decoded is not None:
            if not isinstance(decoded, dict) or decoded.get("v") != 1 or decoded.get("account_id") != account_id:
                out = _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
                return _finalize("failed", out, out["error"]["message"], acct_for_log=account_id)
            start_after = decoded.get("start_after")
            if start_after is not None and (not isinstance(start_after, str) or not re.match(r"^gtsk_tl_[0-9A-Z]{17,}$", start_after)):
                out = _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
                return _finalize("failed", out, out["error"]["message"], acct_for_log=account_id)
        else:
            # Accept raw id cursor (back-compat / observed callers)
            if isinstance(cursor, str) and re.match(r"^gtsk_tl_[0-9A-Z]{17,}$", cursor):
                start_after = cursor
            else:
                out = _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
                return _finalize("failed", out, out["error"]["message"], acct_for_log=account_id)

    accounts = _load("accounts.json")
    if not any(a.get("id") == account_id for a in accounts):
        out = _err("NOT_FOUND", "Account not found.", account_id=account_id)
        return _finalize("failed", out, out["error"]["message"], acct_for_log=account_id)

    tasklists = _load("tasklists.json")
    rows = [tl for tl in tasklists if tl.get("account_id") == account_id]

    # Business rule: list-tasklists returns where status != 'deleted'
    rows = [tl for tl in rows if tl.get("status") != "deleted"]

    # Optional filter by status parameter (even though deleted already excluded)
    if status is not None:
        rows = [tl for tl in rows if tl.get("status") == status]

    # Sort
    reverse = (order == "desc")

    def _sort_key(tl):
        if sort == "title":
            return (str(tl.get("title") or "").lower(), tl.get("id") or "")
        dt = _parse_dt(tl.get(sort))
        # None values last in asc, first in desc; normalize to timestamp
        ts = dt.timestamp() if dt else None
        if ts is None:
            return (1, 0, tl.get("id") or "") if not reverse else (-1, 0, tl.get("id") or "")
        return (0, ts, tl.get("id") or "")

    rows.sort(key=_sort_key, reverse=reverse)

    # Apply cursor (start_after id in the already-sorted list)
    if start_after is not None:
        idx = None
        for i, tl in enumerate(rows):
            if tl.get("id") == start_after:
                idx = i
                break
        if idx is None:
            out = _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
            return _finalize("failed", out, out["error"]["message"], acct_for_log=account_id)
        rows = rows[idx + 1 :]

    total_after_filters = len(rows)
    page = rows[:limit]
    has_more = len(rows) > limit
    next_cursor = None
    if has_more and page:
        next_cursor = _cursor_encode({"v": 1, "account_id": account_id, "start_after": page[-1].get("id")})

    out = {
        "tasklists": page,
        "total": total_after_filters,
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "sort": sort,
        "order": order,
    }
    return _finalize("succeeded", out, None, acct_for_log=account_id)

def get_tasklist(tasklist_id, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0033000" if __import__("os").path.isdir("./environment_mix/0033000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        b = os.urandom(12)
        n = int.from_bytes(b, "big")
        out = []
        for _ in range(18):
            n, r = divmod(n, 36)
            out.append(alphabet[r])
        return prefix + "_" + "".join(out)

    # --- create api request row early (status=received) ---
    api_requests = _load("api_requests.json")
    req_id = _new_id("gtsk_req")
    req_row = {
        "id": req_id,
        "account_id": None,
        "tool_name": "get-tasklist",
        "status": "received",
        "request_payload": {"tasklist_id": tasklist_id},
        "response_payload": None,
        "error_message": None,
        "provider_http_status": None,
        "latency_ms": None,
        "created_at": now,
        "updated_at": now
    }
    api_requests.append(req_row)
    _save("api_requests.json", api_requests)

    def _finalize_ok(resp, resolved_account_id):
        api_requests2 = _load("api_requests.json")
        for r in api_requests2:
            if r.get("id") == req_id:
                r["status"] = "succeeded"
                r["account_id"] = resolved_account_id
                r["response_payload"] = resp
                r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                r["latency_ms"] = max(0, int((time.time() - start) * 1000))
                break
        _save("api_requests.json", api_requests2)
        return resp

    def _finalize_err(err, resolved_account_id=None, provider_http_status=None, error_message=None):
        api_requests2 = _load("api_requests.json")
        for r in api_requests2:
            if r.get("id") == req_id:
                r["status"] = "failed"
                r["account_id"] = resolved_account_id
                r["response_payload"] = {"error": err.get("error")} if isinstance(err, dict) and "error" in err else None
                r["provider_http_status"] = provider_http_status
                r["error_message"] = error_message or (err.get("error", {}).get("message") if isinstance(err, dict) else "Unknown error")
                r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                r["latency_ms"] = max(0, int((time.time() - start) * 1000))
                break
        _save("api_requests.json", api_requests2)
        return err

    # --- validation ---
    if not isinstance(tasklist_id, str) or not re.match(r"^gtsk_tl_[0-9A-Z]{17,}$", tasklist_id):
        return _finalize_err(_err("VALIDATION_ERROR", "Invalid tasklist_id."), None)

    # --- retrieve ---
    tasklists = _load("tasklists.json")
    tl = next((t for t in tasklists if t.get("id") == tasklist_id), None)
    if tl is None or tl.get("status") == "deleted":
        return _finalize_err(_err("NOT_FOUND", "Tasklist not found."), None)

    # --- ambient auth: only allow if an active-ish account exists for the owning account_id ---
    accounts = _load("accounts.json")
    acct = next((a for a in accounts if a.get("id") == tl.get("account_id")), None)
    if acct is None:
        # FK integrity violation in store; treat as not found
        return _finalize_err(_err("NOT_FOUND", "Tasklist not found."), None)

    # With no explicit credentials and no workspace concept, resolve authorization by requiring the account exists.
    # If the store has no viable account context at all, treat as UNAUTHORIZED; here we have one.
    resp = {"tasklist": tl}
    return _finalize_ok(resp, acct.get("id"))

def update_tasklist(tasklist_id, title=None, status=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0033000" if __import__("os").path.isdir("./environment_mix/0033000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _new_req_id():
        return "gtsk_req_" + uuid.uuid4().hex.upper()

    def _append_req(account_id):
        req = {
            "id": _new_req_id(),
            "account_id": account_id,
            "tool_name": "update-tasklist",
            "status": "received",
            "request_payload": {"tasklist_id": tasklist_id, "title": title, "status": status},
            "response_payload": None,
            "error_message": None,
            "provider_http_status": None,
            "latency_ms": None,
            "created_at": now,
            "updated_at": now,
        }
        reqs = _load("api_requests.json")
        reqs.append(req)
        _save("api_requests.json", reqs)
        return req

    def _finalize(req_row, st, resp=None, err=None):
        reqs = _load("api_requests.json")
        for r in reqs:
            if r.get("id") == req_row["id"]:
                r["status"] = st
                r["response_payload"] = resp
                r["error_message"] = err
                r["latency_ms"] = max(0, int((time.time() - t0) * 1000))
                r["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
                break
        _save("api_requests.json", reqs)

    def _rate_limits_ok(account_id_for_limit):
        reqs = _load("api_requests.json")
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        one_min_ago = now_dt - datetime.timedelta(minutes=1)
        day_ago = now_dt - datetime.timedelta(days=1)
        per_min = 0
        per_day = 0
        for r in reqs:
            if account_id_for_limit is None or r.get("account_id") != account_id_for_limit:
                continue
            ca = r.get("created_at")
            if not isinstance(ca, str):
                continue
            try:
                ts = datetime.datetime.fromisoformat(ca.replace("Z", "+00:00"))
            except Exception:
                continue
            if ts >= one_min_ago:
                per_min += 1
            if ts >= day_ago:
                per_day += 1
        if per_min >= 60:
            return _err("RATE_LIMIT", "Rate limit exceeded for account.", limit="60/min", window_seconds=60)
        if per_day >= 10000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded for account.", limit="10000/day", window_seconds=86400)
        return None

    # Validate
    if not isinstance(tasklist_id, str) or not re.match(r"^gtsk_tl_[0-9A-Z]{17,}$", tasklist_id):
        req = _append_req(None)
        out = _err("VALIDATION_ERROR", "tasklist_id is malformed.")
        _finalize(req, "failed", resp={"error": out["error"]}, err=out["error"]["message"])
        return out
    if title is not None and (not isinstance(title, str) or len(title.strip()) < 1):
        req = _append_req(None)
        out = _err("VALIDATION_ERROR", "title must be non-empty when provided.")
        _finalize(req, "failed", resp={"error": out["error"]}, err=out["error"]["message"])
        return out
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "deleted", "archived"):
            req = _append_req(None)
            out = _err("VALIDATION_ERROR", "status must be one of: active, deleted, archived.")
            _finalize(req, "failed", resp={"error": out["error"]}, err=out["error"]["message"])
            return out

    # Load tasklist
    tasklists = _load("tasklists.json")
    tl = next((x for x in tasklists if x.get("id") == tasklist_id), None)
    account_id = tl.get("account_id") if isinstance(tl, dict) else None

    req = _append_req(account_id)

    if not tl:
        out = _err("NOT_FOUND", "Tasklist not found.")
        _finalize(req, "failed", resp={"error": out["error"]}, err=out["error"]["message"])
        return out

    # Rate limit / quota
    rl = _rate_limits_ok(account_id)
    if rl:
        _finalize(req, "failed", resp={"error": rl["error"]}, err=rl["error"]["message"])
        return rl

    # Authorization context: must have active-ish oauth for owning account
    conns = _load("oauth_connections.json")
    ok = any(c.get("account_id") == account_id and c.get("provider") == "google" and c.get("status") in ("token_active", "token_expired") for c in conns)
    if not ok:
        out = _err("UNAUTHORIZED", "No authorized Google OAuth connection for this tasklist's account.")
        _finalize(req, "failed", resp={"error": out["error"]}, err=out["error"]["message"])
        return out

    # Business rules
    if tl.get("status") == "deleted":
        out = _err("CONFLICT", "Cannot update a deleted tasklist.")
        _finalize(req, "failed", resp={"error": out["error"]}, err=out["error"]["message"])
        return out

    # Only allow transitions per lifecycle
    transitions = {"active": ["archived", "deleted"], "archived": ["active", "deleted"], "deleted": []}
    if status is not None and status != tl.get("status"):
        cur = tl.get("status")
        if cur not in transitions or status not in transitions[cur]:
            out = _err("INVALID_TRANSITION", f"Status transition not allowed from '{cur}' to '{status}'.")
            _finalize(req, "failed", resp={"error": out["error"]}, err=out["error"]["message"])
            return out

    changed = False
    if title is not None and title.strip() != tl.get("title"):
        tl["title"] = title.strip()
        changed = True

    if status is not None and status != tl.get("status"):
        tl["status"] = status
        changed = True
        # If deleting via update, cascade delete tasks per rule
        if status == "deleted":
            tasks = _load("tasks.json")
            now_iso = datetime.datetime.now(datetime.timezone.utc).isoformat()
            for t in tasks:
                if t.get("tasklist_id") == tasklist_id and t.get("status") != "deleted":
                    # transition to deleted if allowed
                    t["status"] = "deleted"
                    t["deleted_at"] = now_iso
                    t["updated_at"] = now_iso
            _save("tasks.json", tasks)

    if not changed:
        # No-op is allowed as "update" but must be real: return current row
        resp = {"tasklist": tl}
        _finalize(req, "succeeded", resp=resp)
        return resp

    tl["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
    for i, x in enumerate(tasklists):
        if x.get("id") == tasklist_id:
            tasklists[i] = tl
            break
    _save("tasklists.json", tasklists)

    resp = {"tasklist": tl}
    _finalize(req, "succeeded", resp=resp)
    return resp

