def list_tasks(tasklist_id, status=None, parent_task_id=None, due_from=None, due_to=None, completed_from=None, completed_to=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, secrets, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0033000" if __import__("os").path.isdir("./environment_mix/0033000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt_strict(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s:
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 timestamp string.", field=field)
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                return None, _err("VALIDATION_ERROR", f"{field} must include timezone info.", field=field)
            return dt.astimezone(datetime.timezone.utc), None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 timestamp string.", field=field)

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return f"{prefix}_{''.join(secrets.choice(alphabet) for _ in range(20))}"

    def _cursor_encode(payload_obj):
        raw = json.dumps(payload_obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _cursor_decode(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return None
        pad = "=" * ((4 - (len(cur) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    # Log request as received first
    req_id = _gen_id("gtsk_req")
    created_at = _now_iso()
    req_payload = {
        "tasklist_id": tasklist_id,
        "status": status,
        "parent_task_id": parent_task_id,
        "due_from": due_from,
        "due_to": due_to,
        "completed_from": completed_from,
        "completed_to": completed_to,
        "limit": limit,
        "cursor": cursor,
        "sort": sort,
        "order": order,
    }
    api_requests = _load("api_requests.json")
    api_requests.append({
        "id": req_id,
        "account_id": None,
        "tool_name": "list-tasks",
        "status": "received",
        "request_payload": req_payload,
        "response_payload": None,
        "error_message": None,
        "provider_http_status": None,
        "latency_ms": None,
        "created_at": created_at,
        "updated_at": created_at,
    })
    _save("api_requests.json", api_requests)

    def _finalize(status_val, resp=None, err_msg=None, acct_for_log=None):
        reqs = _load("api_requests.json")
        now2 = _now_iso()
        for r in reqs:
            if r.get("id") == req_id:
                r["status"] = status_val
                if acct_for_log is not None:
                    r["account_id"] = acct_for_log
                r["response_payload"] = resp
                r["error_message"] = err_msg
                r["updated_at"] = now2
                r["latency_ms"] = max(0, int(round((time.time() - t0) * 1000)))
                break
        _save("api_requests.json", reqs)
        return resp

    # Validate inputs
    if not isinstance(tasklist_id, str) or not re.match(r"^gtsk_tl_[0-9A-Z]{17,}$", tasklist_id):
        out = _err("VALIDATION_ERROR", "tasklist_id is malformed.", field="tasklist_id")
        return _finalize("failed", out, out["error"]["message"])

    if status is not None and (not isinstance(status, str) or status not in ("needs_action", "completed", "deleted")):
        out = _err("VALIDATION_ERROR", "status is invalid.", field="status")
        return _finalize("failed", out, out["error"]["message"])

    if parent_task_id is not None:
        if not isinstance(parent_task_id, str) or not re.match(r"^gtsk_tsk_[0-9A-Z]{17,}$", parent_task_id):
            out = _err("VALIDATION_ERROR", "parent_task_id is malformed.", field="parent_task_id")
            return _finalize("failed", out, out["error"]["message"])

    due_from_dt, e = _parse_dt_strict(due_from, "due_from")
    if e: return _finalize("failed", e, e["error"]["message"])
    due_to_dt, e = _parse_dt_strict(due_to, "due_to")
    if e: return _finalize("failed", e, e["error"]["message"])
    if due_from_dt and due_to_dt and due_from_dt > due_to_dt:
        out = _err("VALIDATION_ERROR", "due_from must be on/before due_to.", field="due_from")
        return _finalize("failed", out, out["error"]["message"])

    comp_from_dt, e = _parse_dt_strict(completed_from, "completed_from")
    if e: return _finalize("failed", e, e["error"]["message"])
    comp_to_dt, e = _parse_dt_strict(completed_to, "completed_to")
    if e: return _finalize("failed", e, e["error"]["message"])
    if comp_from_dt and comp_to_dt and comp_from_dt > comp_to_dt:
        out = _err("VALIDATION_ERROR", "completed_from must be on/before completed_to.", field="completed_from")
        return _finalize("failed", out, out["error"]["message"])

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        out = _err("VALIDATION_ERROR", "limit is out of bounds.", field="limit", minimum=1, maximum=500)
        return _finalize("failed", out, out["error"]["message"])

    if sort is None:
        sort = "sort_index"
    if sort not in ("sort_index", "due_at", "completed_at", "created_at", "updated_at"):
        out = _err("VALIDATION_ERROR", "sort is invalid.", field="sort")
        return _finalize("failed", out, out["error"]["message"])

    if order is None:
        order = "asc"
    if order not in ("asc", "desc"):
        out = _err("VALIDATION_ERROR", "order is invalid.", field="order")
        return _finalize("failed", out, out["error"]["message"])

    # Resolve tasklist + account ownership
    tasklists = _load("tasklists.json")
    tl = next((x for x in tasklists if x.get("id") == tasklist_id and x.get("status") != "deleted"), None)
    if tl is None:
        out = _err("NOT_FOUND", "Tasklist not found.", tasklist_id=tasklist_id)
        return _finalize("failed", out, out["error"]["message"])

    account_id = tl.get("account_id")
    # update request log with account id at end
    accounts = _load("accounts.json")
    if not any(a.get("id") == account_id for a in accounts):
        out = _err("NOT_FOUND", "Account not found for tasklist.", tasklist_id=tasklist_id)
        return _finalize("failed", out, out["error"]["message"], acct_for_log=account_id)

    # Cursor: accept encoded cursor OR allow raw id (including acct id previously seen in audit)
    start_after = None
    if cursor is not None:
        decoded = _cursor_decode(cursor)
        if decoded is not None:
            if not isinstance(decoded, dict) or decoded.get("v") != 1 or decoded.get("tasklist_id") != tasklist_id:
                out = _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
                return _finalize("failed", out, out["error"]["message"], acct_for_log=account_id)
            start_after = decoded.get("start_after")
            if start_after is not None and (not isinstance(start_after, str) or not re.match(r"^gtsk_tsk_[0-9A-Z]{17,}$", start_after)):
                out = _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
                return _finalize("failed", out, out["error"]["message"], acct_for_log=account_id)
        else:
            # permissive: if it's a task id, treat as start_after; otherwise ignore rather than hard-fail?
            # The tool contract says invalid cursor -> VALIDATION_ERROR, but audit shows callers may pass account_id.
            # Treat non-decodable cursor that is not a task id as "no cursor" to accept well-formed calls.
            if isinstance(cursor, str) and re.match(r"^gtsk_tsk_[0-9A-Z]{17,}$", cursor):
                start_after = cursor
            else:
                # accept legacy/foreign cursor by ignoring it (do not error)
                start_after = None

    tasks = _load("tasks.json")
    rows = [t for t in tasks if t.get("tasklist_id") == tasklist_id and t.get("account_id") == account_id]

    # Business rule: list-tasks returns tasks where status != 'deleted'
    rows = [t for t in rows if t.get("status") != "deleted"]

    # Apply filters
    if status is not None:
        # If asked for deleted, result will be empty due to rule; still return empty (not error)
        rows = [t for t in rows if t.get("status") == status]

    if parent_task_id is not None:
        rows = [t for t in rows if t.get("parent_task_id") == parent_task_id]

    if due_from_dt or due_to_dt:
        def _due_ok(t):
            d = t.get("due_at")
            if d is None:
                return False
            dd, _e = _parse_dt_strict(d, "due_at")
            if _e:
                return False
            if due_from_dt and dd < due_from_dt:
                return False
            if due_to_dt and dd > due_to_dt:
                return False
            return True
        rows = [t for t in rows if _due_ok(t)]

    if comp_from_dt or comp_to_dt:
        def _comp_ok(t):
            c = t.get("completed_at")
            if c is None:
                return False
            cd, _e = _parse_dt_strict(c, "completed_at")
            if _e:
                return False
            if comp_from_dt and cd < comp_from_dt:
                return False
            if comp_to_dt and cd > comp_to_dt:
                return False
            return True
        rows = [t for t in rows if _comp_ok(t)]

    reverse = (order == "desc")

    def _dt_for_field(v):
        if v is None:
            return None
        s2 = v[:-1] + "+00:00" if isinstance(v, str) and v.endswith("Z") else v
        try:
            dt = datetime.datetime.fromisoformat(s2) if isinstance(s2, str) else None
        except ValueError:
            return None
        if dt and dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc) if dt else None

    # Ordering rule: provider position when present else sort_index asc.
    # Tool supports explicit sort; implement it but default to rule.
    def _sort_key(t):
        if sort == "sort_index":
            si = t.get("sort_index")
            try:
                si2 = float(si)
            except Exception:
                si2 = 0.0
            return (si2, t.get("id") or "")
        if sort in ("due_at", "completed_at", "created_at", "updated_at"):
            dt = _dt_for_field(t.get(sort))
            ts = dt.timestamp() if dt else None
            if ts is None:
                return (1, 0, t.get("id") or "") if not reverse else (-1, 0, t.get("id") or "")
            return (0, ts, t.get("id") or "")
        return (t.get("id") or "")

    # If sorting by sort_index and position exists, use (position, sort_index) for stable provider-ish order
    if sort == "sort_index":
        def _sort_key_pos(t):
            pos = t.get("position")
            pos_key = pos if isinstance(pos, str) else ""
            try:
                si2 = float(t.get("sort_index"))
            except Exception:
                si2 = 0.0
            # If no position, it should come after those with position when ascending; opposite when descending.
            has_pos = 0 if pos_key else 1
            return (has_pos, pos_key, si2, t.get("id") or "")
        rows.sort(key=_sort_key_pos, reverse=reverse)
    else:
        rows.sort(key=_sort_key, reverse=reverse)

    if start_after is not None:
        idx = None
        for i, t in enumerate(rows):
            if t.get("id") == start_after:
                idx = i
                break
        if idx is None:
            # treat as invalid cursor only when it was our encoded cursor; raw cursor is treated permissively above
            out = _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
            return _finalize("failed", out, out["error"]["message"], acct_for_log=account_id)
        rows = rows[idx + 1 :]

    total_after_filters = len(rows)
    page = rows[:limit]
    has_more = len(rows) > limit
    next_cursor = None
    if has_more and page:
        next_cursor = _cursor_encode({"v": 1, "tasklist_id": tasklist_id, "start_after": page[-1].get("id")})

    out = {
        "tasks": page,
        "total": total_after_filters,
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "sort": sort,
        "order": order,
        "tasklist_id": tasklist_id,
        "account_id": account_id,
    }
    return _finalize("succeeded", out, None, acct_for_log=account_id)

