                r["error_message"] = err_msg
                r["updated_at"] = now2
                r["latency_ms"] = max(0, int(round((time.time() - t0) * 1000)))
                break
        _save("api_requests.json", reqs2)
        return resp

    req_id = _gen_req_id()
    created_at = _now_iso()
    req_payload = {"account_id": account_id, "task_id": task_id}

