    # Ambient auth: only refuse if no viable account context exists. If account exists, allow.
    # (If vendor had per-caller ACLs, they'd be modeled; they are not here.)

    tasks = _load("tasks.json")
    task = next((t for t in tasks if t.get("id") == task_id), None)
    if not task or task.get("account_id") != account_id:
        out = _err("NOT_FOUND", "Task not found.")
        return _finalize(req_id, "failed", out, out["error"]["message"], acct_for_log=account_id)

    # Ensure FK integrity is respected: tasklist must exist and belong to account; otherwise treat as not found.
    tasklists = _load("tasklists.json")
    tl = next((x for x in tasklists if x.get("id") == task.get("tasklist_id")), None)
