def create_task(account_id, tasklist_id, title, notes=None, due_at=None, parent_task_id=None, previous_task_id=None, **_extra):
    import json, os, datetime, re, time, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0033000" if __import__("os").path.isdir("./environment_mix/0033000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code0, msg, **x):
        return {"error": {"code": code0, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s:
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 timestamp string.", field=field)
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                return None, _err("VALIDATION_ERROR", f"{field} must include timezone info.", field=field)
            return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z"), None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 timestamp string.", field=field)

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return f"{prefix}_" + "".join(secrets.choice(alphabet) for _ in range(20))

    def _finalize(req_id, status_val, resp, err_msg=None, acct_for_log=None):
        reqs2 = _load("api_requests.json")
        now2 = _now_iso()
        for r in reqs2:
            if r.get("id") == req_id:
                r["status"] = status_val
                if acct_for_log is not None:
                    r["account_id"] = acct_for_log
                r["response_payload"] = resp
                r["error_message"] = err_msg
                r["updated_at"] = now2
                r["latency_ms"] = max(0, int(round((time.time() - t0) * 1000)))
                break
        _save("api_requests.json", reqs2)
        return resp

    req_id = _gen_id("gtsk_req")
    created_at = _now_iso()
    req_payload = {
        "account_id": account_id,
        "tasklist_id": tasklist_id,
        "title": title,
        "notes": notes,
        "due_at": due_at,
        "parent_task_id": parent_task_id,
        "previous_task_id": previous_task_id,
    }

    reqs = _load("api_requests.json")
    reqs.append(
        {
            "id": req_id,
            "account_id": account_id if isinstance(account_id, str) else None,
            "tool_name": "create-task",
            "status": "received",
            "request_payload": req_payload,
            "response_payload": None,
            "error_message": None,
            "provider_http_status": None,
            "latency_ms": None,
            "created_at": created_at,
            "updated_at": created_at,
        }
    )
    _save("api_requests.json", reqs)

    if not isinstance(account_id, str) or not re.match(r"^gtsk_acct_[0-9A-Z]{18,}$", account_id):
        out = _err("VALIDATION_ERROR", "account_id is malformed.", field="account_id")
        return _finalize(req_id, "failed", out, out["error"]["message"])
    if not isinstance(tasklist_id, str) or not re.match(r"^gtsk_tl_[0-9A-Z]{18,}$", tasklist_id):
        out = _err("VALIDATION_ERROR", "tasklist_id is malformed.", field="tasklist_id")
        return _finalize(req_id, "failed", out, out["error"]["message"], acct_for_log=account_id)
    if not isinstance(title, str) or title.strip() == "":
        out = _err("VALIDATION_ERROR", "title is required and must be non-empty.", field="title")
        return _finalize(req_id, "failed", out, out["error"]["message"], acct_for_log=account_id)

    if notes is not None and not isinstance(notes, str):
        out = _err("VALIDATION_ERROR", "notes must be a string.", field="notes")
        return _finalize(req_id, "failed", out, out["error"]["message"], acct_for_log=account_id)

    due_parsed, derr = _parse_rfc3339(due_at, "due_at")
    if derr:
        return _finalize(req_id, "failed", derr, derr["error"]["message"], acct_for_log=account_id)

    # Relax validation: only validate previous_task_id/parent_task_id when they look like task ids;
    # Do not fail the whole request on "malformed" if caller accidentally passed some other id value;
    # treat it as "incompatible with tasklist" like real systems tend to do.
    if parent_task_id is not None and not (isinstance(parent_task_id, str) and re.match(r"^gtsk_tsk_[0-9A-Z]{18,}$", parent_task_id)):
        out = _err("VALIDATION_ERROR", "parent_task_id is malformed.", field="parent_task_id")
        return _finalize(req_id, "failed", out, out["error"]["message"], acct_for_log=account_id)
    if previous_task_id is not None and not (isinstance(previous_task_id, str) and re.match(r"^gtsk_tsk_[0-9A-Z]{18,}$", previous_task_id)):
        # Keep message aligned to schema, but allow request to proceed when clearly not a task id by treating as incompatible
        out = _err("VALIDATION_ERROR", "previous_task_id is malformed.", field="previous_task_id")
        return _finalize(req_id, "failed", out, out["error"]["message"], acct_for_log=account_id)

    accounts = _load("accounts.json")
    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if not acct:
        out = _err("NOT_FOUND", "Account not found.", field="account_id")
        return _finalize(req_id, "failed", out, out["error"]["message"])

    tasklists = _load("tasklists.json")
    tl = next((t for t in tasklists if t.get("id") == tasklist_id and t.get("account_id") == account_id), None)
    if not tl or tl.get("status") == "deleted":
        out = _err("NOT_FOUND", "Tasklist not found.")
        return _finalize(req_id, "failed", out, out["error"]["message"], acct_for_log=account_id)

    tasks = _load("tasks.json")

    # parent_task_id must refer to a task in same tasklist (and same account)
    if parent_task_id is not None:
        parent = next((t for t in tasks if t.get("id") == parent_task_id), None)
        if not parent or parent.get("account_id") != account_id or parent.get("tasklist_id") != tasklist_id or parent.get("status") == "deleted":
            out = _err("VALIDATION_ERROR", "parent_task_id must refer to a task in the same tasklist.", field="parent_task_id")
            return _finalize(req_id, "failed", out, out["error"]["message"], acct_for_log=account_id)

    # previous_task_id must refer to a task in same tasklist (and same parent if provided)
    if previous_task_id is not None:
        prev = next((t for t in tasks if t.get("id") == previous_task_id), None)
        if not prev or prev.get("account_id") != account_id or prev.get("tasklist_id") != tasklist_id or prev.get("status") == "deleted":
            out = _err("VALIDATION_ERROR", "previous_task_id must refer to a task in the same tasklist.", field="previous_task_id")
            return _finalize(req_id, "failed", out, out["error"]["message"], acct_for_log=account_id)
        if parent_task_id is not None and prev.get("parent_task_id") != parent_task_id:
            out = _err("VALIDATION_ERROR", "previous_task_id must refer to a sibling under the same parent_task_id.", field="previous_task_id")
            return _finalize(req_id, "failed", out, out["error"]["message"], acct_for_log=account_id)

    # sort_index: max+1 within tasklist (business rule)
    max_si = -1
    for t in tasks:
        if t.get("tasklist_id") == tasklist_id:
            try:
                si = float(t.get("sort_index", 0))
            except Exception:
                si = 0
            if si > max_si:
                max_si = si
    new_sort_index = int(max_si + 1) if max_si >= 0 else 0

    # If previous_task_id provided, insert after it by assigning midpoint and renormalizing to integers.
    if previous_task_id is not None:
        siblings = [t for t in tasks if t.get("tasklist_id") == tasklist_id and t.get("status") != "deleted" and t.get("parent_task_id") == parent_task_id]
        siblings.sort(key=lambda x: (x.get("sort_index", 0), x.get("created_at", "")))
        prev_idx = next((i for i, t in enumerate(siblings) if t.get("id") == previous_task_id), None)
        if prev_idx is None:
            out = _err("VALIDATION_ERROR", "previous_task_id must refer to a task in the same tasklist.", field="previous_task_id")
            return _finalize(req_id, "failed", out, out["error"]["message"], acct_for_log=account_id)
        # compute new index
        if prev_idx == len(siblings) - 1:
            new_sort_index = int(siblings[-1].get("sort_index", 0)) + 1
        else:
            a = float(siblings[prev_idx].get("sort_index", 0))
            b = float(siblings[prev_idx + 1].get("sort_index", a + 2))
            mid = (a + b) / 2.0
            new_sort_index = mid
        # renormalize to strictly increasing integers for all tasks in tasklist (business rule used by move-task)
        # We'll do this after inserting row.

    now = _now_iso()
    new_task = {
        "id": _gen_id("gtsk_tsk"),
        "account_id": account_id,
        "tasklist_id": tasklist_id,
        "google_task_id": _gen_id("gtask").lower(),  # placeholder provider id; must be unique within tasklist
        "title": title,
        "notes": notes,
        "status": "needs_action",
        "due_at": due_parsed,
        "completed_at": None,
        "deleted_at": None,
        "parent_task_id": parent_task_id,
        "position": None,
        "sort_index": new_sort_index if isinstance(new_sort_index, int) else float(new_sort_index),
        "etag": None,
        "self_link": None,
        "last_synced_at": None,
        "created_at": now,
        "updated_at": now,
    }

    # Ensure unique(tasklist_id, google_task_id)
    existing_google_ids = {t.get("google_task_id") for t in tasks if t.get("tasklist_id") == tasklist_id}
    if new_task["google_task_id"] in existing_google_ids:
        new_task["google_task_id"] = _gen_id("gtask").lower()

    tasks.append(new_task)

    # Renormalize sort_index within tasklist to unique, strictly increasing integers while preserving order by sort_index
    def _renormalize(tasklist_id0):
        subset = [t for t in tasks if t.get("tasklist_id") == tasklist_id0]
        subset.sort(key=lambda x: (float(x.get("sort_index", 0) or 0), x.get("created_at", ""), x.get("id", "")))
        for i, t in enumerate(subset):
            t["sort_index"] = i

    _renormalize(tasklist_id)
    _save("tasks.json", tasks)

    resp = {"task": new_task}
    return _finalize(req_id, "succeeded", resp, None, acct_for_log=account_id)

def update_task(account_id, task_id, title=None, notes=None, due_at=None, status=None, completed_at=None, **_extra):
