    # Lifecycle transitions (per schema): needs_action <-> completed, and either -> deleted (handled elsewhere)
    current = task.get("status")
    if status is not None and status != current:
        allowed = {"needs_action": ["completed", "deleted"], "completed": ["needs_action", "deleted"], "deleted": []}
