                task["completed_at"] = None

    # completed_at updates allowed (as per tool description), but must be consistent with status=completed
    if comp_parsed is not None:
        task["completed_at"] = comp_parsed
        if task.get("status") != "completed":
            # enforce constraint: completed_at is null or status='completed'
