    if due_at is not None:
        task["due_at"] = due_parsed

    if title is not None:
        task["title"] = title
    if notes is not None:
        task["notes"] = notes

    task["updated_at"] = _now_iso()
    tasks[idx] = task
    _save("tasks.json", tasks)

    resp = {"task": task}
    return _finalize(req_id, "succeeded", resp, None, acct_for_log=account_id)

