    src_tl = next((t for t in tasklists if t.get("id") == src_tasklist_id and t.get("account_id") == account_id), None)
    dst_tl = next((t for t in tasklists if t.get("id") == dst_tasklist_id and t.get("account_id") == account_id), None)
