        prev = next((t for t in tasks if t.get("id") == previous_task_id), None)
        if not prev or prev.get("account_id") != account_id or prev.get("tasklist_id") != dst_tasklist_id or prev.get("status") == "deleted":
            out = _err("VALIDATION_ERROR", "previous_task_id must refer to a task in the destination tasklist.", field="previous_task_id")
            return _finalize(req_id, "failed", out, out["error"]["message"], acct_for_log=account_id)
        if prev.get("parent_task_id") != parent_task_id:
            out = _err("VALIDATION_ERROR", "previous_task_id must refer to a sibling under the same parent_task_id.", field="previous_task_id")
            return _finalize(req_id, "failed", out, out["error"]["message"], acct_for_log=account_id)

    # Move
    task["tasklist_id"] = dst_tasklist_id
    task["parent_task_id"] = parent_task_id

    # Recompute ordering: keep unique, strictly increasing sort_index in destination list
    dst_all = [t for t in tasks if t.get("tasklist_id") == dst_tasklist_id]
    dst_all_active = [t for t in dst_all if t.get("status") != "deleted"]

    # For insertion ordering, use siblings under same parent
    siblings = [t for t in dst_all_active if t.get("parent_task_id") == parent_task_id and t.get("id") != task_id]
    siblings.sort(key=lambda x: (float(x.get("sort_index", 0) or 0), x.get("created_at", ""), x.get("id", "")))

    insert_pos = 0
    if previous_task_id is None:
        insert_pos = 0
    else:
        prev_idx = next((i for i, t in enumerate(siblings) if t.get("id") == previous_task_id), None)
        insert_pos = (prev_idx + 1) if prev_idx is not None else len(siblings)

    # Build new ordered list for renormalization within destination tasklist
    # We'll preserve relative order for non-siblings by sorting by current sort_index after we update this task.
    # First, set a provisional sort_index that will place it near its siblings window.
    if siblings:
        if insert_pos == 0:
            provisional = float(siblings[0].get("sort_index", 0)) - 1.0
        elif insert_pos >= len(siblings):
            provisional = float(siblings[-1].get("sort_index", 0)) + 1.0
        else:
            a = float(siblings[insert_pos - 1].get("sort_index", 0))
            b = float(siblings[insert_pos].get("sort_index", a + 2))
            provisional = (a + b) / 2.0
    else:
        provisional = 0.0
    task["sort_index"] = provisional
    task["updated_at"] = _now_iso()
    tasks[idx] = task

    # Renormalize destination tasklist to strictly increasing integers (business rule)
    def _renormalize(tasklist_id0):
        subset = [t for t in tasks if t.get("tasklist_id") == tasklist_id0]
        subset.sort(key=lambda x: (float(x.get("sort_index", 0) or 0), x.get("created_at", ""), x.get("id", "")))
        for i, t in enumerate(subset):
            t["sort_index"] = i

    _renormalize(dst_tasklist_id)
    if src_tasklist_id != dst_tasklist_id:
        _renormalize(src_tasklist_id)

    _save("tasks.json", tasks)

    resp = {"task": task}
    return _finalize(req_id, "succeeded", resp, None, acct_for_log=account_id)

def clear_completed_tasks(account_id, tasklist_id, **_extra):
    import json, os, datetime, re, time, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0033000" if __import__("os").path.isdir("./environment_mix/0033000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _gen_req_id():
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return "gtsk_req_" + "".join(secrets.choice(alphabet) for _ in range(20))

    def _finalize(req_id, status_val, resp, err_msg=None, acct_for_log=None):
        reqs2 = _load("api_requests.json")
        now2 = _now_iso()
        for r in reqs2:
            if r.get("id") == req_id:
                r["status"] = status_val
                if acct_for_log is not None:
                    r["account_id"] = acct_for_log
                r["response_payload"] = resp
                r["error_message"] = err_msg
                r["updated_at"] = now2
                r["latency_ms"] = max(0, int(round((time.time() - t0) * 1000)))
                break
        _save("api_requests.json", reqs2)
        return resp

    req_id = _gen_req_id()
    created_at = _now_iso()
    req_payload = {"account_id": account_id, "tasklist_id": tasklist_id}
    reqs = _load("api_requests.json")
    reqs.append(
        {
            "id": req_id,
            "account_id": account_id if isinstance(account_id, str) else None,
            "tool_name": "clear-completed-tasks",
            "status": "received",
            "request_payload": req_payload,
            "response_payload": None,
            "error_message": None,
            "provider_http_status": None,
            "latency_ms": None,
            "created_at": created_at,
            "updated_at": created_at,
        }
    )
    _save("api_requests.json", reqs)

    if not isinstance(account_id, str) or not re.match(r"^gtsk_acct_[0-9A-Z]{18,}$", account_id):
        out = _err("VALIDATION_ERROR", "account_id is malformed.", field="account_id")
        return _finalize(req_id, "failed", out, out["error"]["message"])
    if not isinstance(tasklist_id, str) or not re.match(r"^gtsk_tl_[0-9A-Z]{18,}$", tasklist_id):
        out = _err("VALIDATION_ERROR", "tasklist_id is malformed.", field="tasklist_id")
        return _finalize(req_id, "failed", out, out["error"]["message"], acct_for_log=account_id)

    accounts = _load("accounts.json")
    if not any(a.get("id") == account_id for a in accounts):
        out = _err("NOT_FOUND", "Account not found.", field="account_id")
        return _finalize(req_id, "failed", out, out["error"]["message"])

    tasklists = _load("tasklists.json")
    tl = next((t for t in tasklists if t.get("id") == tasklist_id and t.get("account_id") == account_id), None)
    if not tl or tl.get("status") == "deleted":
        out = _err("NOT_FOUND", "Tasklist not found.")
        return _finalize(req_id, "failed", out, out["error"]["message"], acct_for_log=account_id)

    tasks = _load("tasks.json")
    now = _now_iso()

    cleared_ids = []
    affected = 0
    for t in tasks:
        if t.get("account_id") == account_id and t.get("tasklist_id") == tasklist_id and t.get("status") == "completed":
            # Clear completed => delete (soft-delete)
            t["status"] = "deleted"
            t["deleted_at"] = now
            t["updated_at"] = now
            cleared_ids.append(t.get("id"))
            affected += 1

    if affected == 0:
        # Real API: success with zero cleared is still an effect? It's a mutation but can be a no-op.
        # Contract says "NO SUCCESS WITHOUT EFFECT" for mutations that matched no row.
        # Here, rows matching criteria are the completed tasks; if none exist, return NOT_FOUND-like?
        # Better: treat as succeeded with cleared_count=0? But contract forbids.
        out = _err("NOT_FOUND", "No completed tasks found to clear.")
        return _finalize(req_id, "failed", out, out["error"]["message"], acct_for_log=account_id)

    _save("tasks.json", tasks)

    resp = {"tasklist_id": tasklist_id, "cleared_count": affected, "cleared_task_ids": cleared_ids}
    return _finalize(req_id, "succeeded", resp, None, acct_for_log=account_id)

def me(authorization, **_extra):
