            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return f"{prefix}_{''.join(secrets.choice(alphabet) for _ in range(20))}"

    # Log received
    req_id = _gen_id("gtsk_req")
    created_at = _now_iso()
    reqs = _load("api_requests.json")
    reqs.append({
        "id": req_id,
        "account_id": None,
        "tool_name": "me",
        "status": "received",
        "request_payload": {"authorization": authorization},
        "response_payload": None,
        "error_message": None,
        "provider_http_status": None,
        "latency_ms": None,
        "created_at": created_at,
        "updated_at": created_at,
    })
    _save("api_requests.json", reqs)

    def _finalize(status_val, resp, err_msg=None, acct_for_log=None):
        reqs2 = _load("api_requests.json")
        now2 = _now_iso()
        for r in reqs2:
            if r.get("id") == req_id:
                r["status"] = status_val
                if acct_for_log is not None:
                    r["account_id"] = acct_for_log
                r["response_payload"] = resp
                r["error_message"] = err_msg
                r["updated_at"] = now2
                r["latency_ms"] = max(0, int(round((time.time() - t0) * 1000)))
                break
        _save("api_requests.json", reqs2)
        return resp

    # Authenticate: parameter can be 'Bearer <token>' where token may be an account id (as seen in audit),
    # or may be a raw token/id. Since no credentials collection exists in schema, treat account_id as credential.
    if not isinstance(authorization, str) or not authorization.strip():
        out = _err("UNAUTHORIZED", "Invalid or missing authorization.")
        return _finalize("failed", out, out["error"]["message"])

    token = authorization.strip()
    if token.lower().startswith("bearer "):
        token = token.split(" ", 1)[1].strip()

    accounts = _load("accounts.json")
    # accept token matching account id; otherwise unauthorized
    acct = next((a for a in accounts if a.get("id") == token), None)
    if acct is None:
        out = _err("UNAUTHORIZED", "Invalid or missing authorization.")
        return _finalize("failed", out, out["error"]["message"])

    # Scopes from oauth connection if present
    oauth = _load("oauth_connections.json")
    conn = next((c for c in oauth if c.get("account_id") == acct.get("id") and c.get("provider") == "google"), None)
    scopes = conn.get("scopes") if isinstance(conn, dict) else None
    if not isinstance(scopes, list):
        scopes = []

    # Basic usage from api_requests (last 60s + last 24h)
    reqs_all = _load("api_requests.json")
    now_dt = datetime.datetime.now(datetime.timezone.utc)

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    last_60s = 0
    last_24h = 0
    for r in reqs_all:
        if r.get("account_id") != acct.get("id"):
            continue
        dt = _parse_dt(r.get("created_at"))
        if not dt:
            continue
        delta = (now_dt - dt).total_seconds()
        if 0 <= delta <= 60:
            last_60s += 1
        if 0 <= delta <= 86400:
            last_24h += 1

    out = {
        "account": acct,
        "scopes": scopes,
        "usage": {
            "requests_last_60s": last_60s,
            "requests_last_24h": last_24h,
        },
        "authorization": {"type": "bearer", "token_id": acct.get("id")},
    }
    return _finalize("succeeded", out, None, acct_for_log=acct.get("id"))

def list_accounts(authorization, status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, re, secrets, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0033000" if __import__("os").path.isdir("./environment_mix/0033000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return f"{prefix}_{''.join(secrets.choice(alphabet) for _ in range(20))}"

    def _cursor_encode(payload_obj):
        raw = json.dumps(payload_obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _cursor_decode(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return None
        pad = "=" * ((4 - (len(cur) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    # Log received
    req_id = _gen_id("gtsk_req")
    created_at = _now_iso()
    req_payload = {"authorization": authorization, "status": status, "limit": limit, "cursor": cursor, "sort": sort, "order": order}
    reqs = _load("api_requests.json")
    reqs.append({
        "id": req_id,
        "account_id": None,
        "tool_name": "list-accounts",
        "status": "received",
        "request_payload": req_payload,
        "response_payload": None,
        "error_message": None,
        "provider_http_status": None,
        "latency_ms": None,
        "created_at": created_at,
        "updated_at": created_at,
    })
    _save("api_requests.json", reqs)

    def _finalize(status_val, resp, err_msg=None, acct_for_log=None):
        reqs2 = _load("api_requests.json")
        now2 = _now_iso()
        for r in reqs2:
            if r.get("id") == req_id:
                r["status"] = status_val
                if acct_for_log is not None:
                    r["account_id"] = acct_for_log
                r["response_payload"] = resp
                r["error_message"] = err_msg
                r["updated_at"] = now2
                r["latency_ms"] = max(0, int(round((time.time() - t0) * 1000)))
                break
        _save("api_requests.json", reqs2)
        return resp

    # Authenticate similarly to me(): token can be 'Bearer <account_id>'
    if not isinstance(authorization, str) or not authorization.strip():
        out = _err("UNAUTHORIZED", "Invalid or missing authorization.")
        return _finalize("failed", out, out["error"]["message"])

    token = authorization.strip()
    if token.lower().startswith("bearer "):
        token = token.split(" ", 1)[1].strip()

    accounts = _load("accounts.json")
    caller = next((a for a in accounts if a.get("id") == token), None)
    if caller is None:
        out = _err("UNAUTHORIZED", "Invalid or missing authorization.")
        return _finalize("failed", out, out["error"]["message"])

    # Validate filters
    if status is not None and (not isinstance(status, str) or status not in ("pending_auth", "active", "revoked", "error")):
        out = _err("VALIDATION_ERROR", "status is invalid.", field="status")
        return _finalize("failed", out, out["error"]["message"], acct_for_log=caller.get("id"))

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        out = _err("VALIDATION_ERROR", "limit is out of bounds.", field="limit", minimum=1, maximum=200)
        return _finalize("failed", out, out["error"]["message"], acct_for_log=caller.get("id"))

    if sort is None:
        sort = "updated_at"
    if sort not in ("created_at", "updated_at", "email", "last_sync_at"):
        out = _err("VALIDATION_ERROR", "sort is invalid.", field="sort")
        return _finalize("failed", out, out["error"]["message"], acct_for_log=caller.get("id"))

    if order is None:
        order = "desc"
    if order not in ("asc", "desc"):
        out = _err("VALIDATION_ERROR", "order is invalid.", field="order")
        return _finalize("failed", out, out["error"]["message"], acct_for_log=caller.get("id"))

    # Cursor
    start_after = None
    if cursor is not None:
        decoded = _cursor_decode(cursor)
        if decoded is not None:
            if not isinstance(decoded, dict) or decoded.get("v") != 1:
                out = _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
                return _finalize("failed", out, out["error"]["message"], acct_for_log=caller.get("id"))
            start_after = decoded.get("start_after")
        else:
            # accept raw account id as cursor
            if isinstance(cursor, str) and re.match(r"^gtsk_acct_[0-9A-Z]{17,}$", cursor):
                start_after = cursor
            else:
                out = _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
                return _finalize("failed", out, out["error"]["message"], acct_for_log=caller.get("id"))

    rows = list(accounts)
    if status is not None:
        rows = [a for a in rows if a.get("status") == status]

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    reverse = (order == "desc")
    def _sort_key(a):
        if sort in ("created_at", "updated_at", "last_sync_at"):
            dt = _parse_dt(a.get(sort))
            ts = dt.timestamp() if dt else None
            if ts is None:
                return (1, 0, a.get("id") or "") if not reverse else (-1, 0, a.get("id") or "")
            return (0, ts, a.get("id") or "")
        if sort == "email":
            return (str(a.get("email") or "").lower(), a.get("id") or "")
        return (a.get("id") or "")

    rows.sort(key=_sort_key, reverse=reverse)

    if start_after is not None:
        idx = None
        for i, a in enumerate(rows):
            if a.get("id") == start_after:
                idx = i
                break
        if idx is None:
            out = _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
            return _finalize("failed", out, out["error"]["message"], acct_for_log=caller.get("id"))
        rows = rows[idx + 1 :]

    total = len(rows)
    page = rows[:limit]
    has_more = len(rows) > limit
    next_cursor = None
    if has_more and page:
        next_cursor = _cursor_encode({"v": 1, "start_after": page[-1].get("id")})

    out = {"accounts": page, "total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor, "sort": sort, "order": order}
    return _finalize("succeeded", out, None, acct_for_log=caller.get("id"))

