def revoke_account(authorization, account_id, reason=None, **_extra):
    import json, os, datetime, time, re, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0033000" if __import__("os").path.isdir("./environment_mix/0033000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code0, msg, **x):
        return {"error": {"code": code0, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _gen_req_id():
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return "gtsk_req_" + "".join(secrets.choice(alphabet) for _ in range(20))

    def _finalize(req_id, status_val, resp, err_msg=None, acct_for_log=None, provider_http_status=None):
        reqs2 = _load("api_requests.json")
        now2 = _now_iso()
        for r in reqs2:
            if r.get("id") == req_id:
                r["status"] = status_val
                if acct_for_log is not None:
                    r["account_id"] = acct_for_log
                r["response_payload"] = resp
                r["error_message"] = err_msg
                r["provider_http_status"] = provider_http_status
                r["updated_at"] = now2
                r["latency_ms"] = max(0, int(round((time.time() - t0) * 1000)))
                break
        _save("api_requests.json", reqs2)
        return resp

    req_id = _gen_req_id()
    created_at = _now_iso()
    req_payload = {"authorization": authorization, "account_id": account_id, "reason": reason}

    reqs = _load("api_requests.json")
    reqs.append(
        {
            "id": req_id,
            "account_id": account_id if isinstance(account_id, str) else None,
            "tool_name": "revoke-account",
            "status": "received",
            "request_payload": req_payload,
            "response_payload": None,
            "error_message": None,
            "provider_http_status": None,
            "latency_ms": None,
            "created_at": created_at,
            "updated_at": created_at,
        }
    )
    _save("api_requests.json", reqs)

    # Validate basic inputs
    if not isinstance(account_id, str) or not re.match(r"^gtsk_acct_[0-9A-Z]{17,}$", account_id):
        out = _err("VALIDATION_ERROR", "account_id is malformed.", field="account_id")
        return _finalize(req_id, "failed", out, out["error"]["message"])
    if reason is not None and (not isinstance(reason, str) or len(reason) > 500):
        out = _err("VALIDATION_ERROR", "reason must be a string of at most 500 characters.", field="reason")
        return _finalize(req_id, "failed", out, out["error"]["message"], acct_for_log=account_id)

    # Authenticate: match bearer token against any client-visible stored token-like value or id.
    # Since store schema doesn't define an API-keys table, treat oauth_connections.access_token_ciphertext
    # as opaque and NEVER compare against ciphertext; instead allow any non-empty Bearer and rely on existence
    # of the account+connection as authorization context (ambient for this dataset).
    if not isinstance(authorization, str) or not authorization.startswith("Bearer ") or not authorization.strip()[7:]:
        out = _err("UNAUTHORIZED", "Invalid or missing authorization.")
        return _finalize(req_id, "failed", out, out["error"]["message"])
    bearer = authorization.strip()[7:]

    accounts = _load("accounts.json")
    oauths = _load("oauth_connections.json")

    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if not acct:
        out = _err("NOT_FOUND", "Account not found.", field="account_id")
        return _finalize(req_id, "failed", out, out["error"]["message"])

    # Find a working auth context: any oauth connection for this account in a state that indicates prior auth.
    # Also allow matching the bearer token to oauth connection id (client-visible).
    conn = None
    for c in oauths:
        if c.get("account_id") != account_id or c.get("provider") != "google":
            continue
        if bearer == c.get("id"):
            conn = c
            break
        if c.get("status") in ("token_active", "token_expired", "code_received", "needs_consent", "error", "revoked"):
            conn = c
            # keep searching for id match but we accept any for this account
    if conn is None:
        # If no connection rows exist for this account, cannot revoke tokens.
        out = _err("UNAUTHORIZED", "Invalid or missing authorization.")
        return _finalize(req_id, "failed", out, out["error"]["message"], acct_for_log=account_id)

    # Enforce lifecycle transitions
    acct_transitions = {
        "pending_auth": ["active", "error"],
        "active": ["revoked", "error"],
        "error": ["pending_auth", "revoked"],
        "revoked": ["pending_auth"],
    }
    oauth_transitions = {
        "needs_consent": ["code_received", "error"],
        "code_received": ["token_active", "error"],
        "token_active": ["token_expired", "revoked", "error"],
        "token_expired": ["token_active", "revoked", "error"],
        "error": ["needs_consent", "code_received", "revoked"],
        "revoked": ["needs_consent"],
    }

    if "revoked" not in acct_transitions.get(acct.get("status"), []):
        out = _err("CONFLICT", f"Account cannot be revoked from status '{acct.get('status')}'.")
        return _finalize(req_id, "failed", out, out["error"]["message"], acct_for_log=account_id)

    if "revoked" not in oauth_transitions.get(conn.get("status"), []) and conn.get("status") != "revoked":
        out = _err("CONFLICT", f"OAuth connection cannot be revoked from status '{conn.get('status')}'.")
        return _finalize(req_id, "failed", out, out["error"]["message"], acct_for_log=account_id)

    now = _now_iso()
    # Mutate account
    for i, a in enumerate(accounts):
        if a.get("id") == account_id:
            a["status"] = "revoked"
            a["updated_at"] = now
            accounts[i] = a
            acct = a
            break

    # Mutate oauth connection
    for i, c in enumerate(oauths):
        if c.get("id") == conn.get("id"):
            c["status"] = "revoked"
            c["access_token_ciphertext"] = c.get("access_token_ciphertext")  # keep as-is (server would revoke externally)
            c["refresh_token_ciphertext"] = c.get("refresh_token_ciphertext")
            c["last_error_code"] = None
            c["last_error_message"] = None
            c["updated_at"] = now
            oauths[i] = c
            conn = c
            break

    _save("accounts.json", accounts)
    _save("oauth_connections.json", oauths)

    resp = {"account": acct, "oauth_connection": conn, "reason": reason}
    return _finalize(req_id, "succeeded", resp, None, acct_for_log=account_id)
